def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((color, cells))

    object_colors = {color for color, cells in components if len(cells) >= 4}
    out = [[bg if grid[r][c] != bg and grid[r][c] not in object_colors else grid[r][c]
            for c in range(w)] for r in range(h)]

    for color, cells in components:
        if color in object_colors:
            r0 = min(r for r, c in cells)
            r1 = max(r for r, c in cells)
            c0 = min(c for r, c in cells)
            c1 = max(c for r, c in cells)
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = color

    return out
